    expected_agent_adapter_ref: str | None = None
    expected_agent_model_adapter_ref: str | None = None
    expected_model_provider_ref: str | None = None
    expected_source_coverage_ref: str | None = None
    expected_dynamic_source_runtime_ref: str | None = None
    expected_browser_snapshot_ref: str | None = None
    expected_browser_quality_ref: str | None = None
    expected_deep_crawl_ref: str | None = None
    expected_field_oracle_ref: str | None = None
    expected_quality_metrics_ref: str | None = None
    expected_repair_quality_ref: str | None = None
    expected_quality_release_ref: str | None = None
    expected_product_availability_ref: str | None = None
    expected_product_discovery_ref: str | None = None
    expected_crawler_optimization_ref: str | None = None
    expected_credentialed_session_ref: str | None = None
